// 模拟用户数据
const mockUserProfile = {
  avatar:'data:image/png;base64,',// 模拟的 base64 头像
  nickname: '测试用户',
  birthday: '19990315', // yyyyMMdd格式
  gender: '男',
  company: '某某科技有限公司',
  position: '前端工程师',
  school: '某某大学',
  introduction: '这是一段个人介绍',
  createTime: '2024-01-01 12:00:00',
  updateTime: '2024-01-01 12:00:00'
}

// 获取用户信息
export const getUserProfile = () => {
  return {
    code: 0,
    message: 'success',
    data: mockUserProfile
  }
}

// 创建用户信息
export const createProfile = (params) => {
  return {
    code: 0,
    message: 'success',
    data: {
      ...mockUserProfile,
      ...params,
      updateTime: Date.now()
    }
  }
}

// 更新用户信息
export const updateProfile = (params) => {
  return {
    code: 0,
    message: 'success',
    data: {
      ...mockUserProfile,
      ...params,
      updateTime: Date.now()
    }
  }
} 